 if ( ! defined( 'ABSPATH' ) ) { exit; } require_once __DIR__ . '/class-mixer-all.php'; class HVM_Widget_StickyProbar extends HVM_Widget_Base { public function get_name() { return 'hvm_sticky_probar'; } public function get_title() { return 'Mixer Sticky Probar'; } public function get_icon() { return 'eicon-anchor'; } protected function register_controls() { $cm = '\Elementor\Controls_Manager'; $this->start_controls_section( 'sp_content', array( 'label' => 'Content', 'tab' => constant( "$cm::TAB_CONTENT" ) ) ); $this->add_control( 'status_text', array( 'label' => 'Status text', 'type' => constant( "$cm::TEXT" ), 'default' => 'Limited places remaining' ) ); $this->add_control( 'cta_text', array( 'label' => 'Button text', 'type' => constant( "$cm::TEXT" ), 'default' => 'Get Tickets' ) ); $this->add_control( 'scroll_after', array( 'label' => 'Reveal after scrolling (px)', 'type' => constant( "$cm::NUMBER" ), 'default' => 100, 'min' => 0, 'description' => 'On the live page the bar slides up from the bottom once you scroll past this depth, and slides away when you return above it. Small value = pops up as soon as you start scrolling. In the editor it stays inline.', ) ); $this->end_controls_section(); $this->start_controls_section( 'sp_bar', array( 'label' => 'Bar', 'tab' => constant( "$cm::TAB_STYLE" ) ) ); $this->add_control( 'bar_bg', array( 'label' => 'Background', 'type' => constant( "$cm::COLOR" ), 'default' => '#010055', 'selectors' => array( '{{WRAPPER}} .hvm-sticky' => 'background:{{VALUE}};' ) ) ); $this->add_group_control( \Elementor\Group_Control_Border::get_type(), array( 'name' => 'bar_border', 'selector' => '{{WRAPPER}} .hvm-sticky' ) ); $this->add_responsive_control( 'bar_radius', array( 'label' => 'Border radius', 'type' => constant( "$cm::SLIDER" ), 'size_units' => array( 'px', '%' ), 'range' => array( 'px' => array( 'min' => 0, 'max' => 100 ) ), 'default' => array( 'unit' => 'px', 'size' => 64 ), 'selectors' => array( '{{WRAPPER}} .hvm-sticky' => 'borde