Left', 'right top' => 'Top Right', 'center bottom' => 'Bottom Center', 'left bottom' => 'Bottom Left', 'right bottom' => 'Bottom Right', ), 'selectors' => array( '{{WRAPPER}} .hvm-sticky-logo img' => 'object-position:{{VALUE}};' ) ) ); $this->end_controls_section(); $this->start_controls_section( 'sp_btn', array( 'label' => 'Button', 'tab' => constant( "$cm::TAB_STYLE" ) ) ); $b = '{{WRAPPER}} .hvm-sticky-btn .elementor-button'; $this->add_control( 'btn_color', array( 'label' => 'Text color', 'type' => constant( "$cm::COLOR" ), 'selectors' => array( $b => 'color:{{VALUE}} !important;' ) ) ); $this->add_control( 'btn_bg', array( 'label' => 'Background', 'type' => constant( "$cm::COLOR" ), 'selectors' => array( $b => 'background:{{VALUE}} !important;' ) ) ); $this->add_group_control( \Elementor\Group_Control_Typography::get_type(), array( 'name' => 'btn_typo', 'selector' => $b . ', ' . $b . ' .elementor-button-text' ) ); $this->add_group_control( \Elementor\Group_Control_Border::get_type(), array( 'name' => 'btn_border', 'selector' => $b, 'fields_options' => array( 'border' => array( 'selectors' => array( $b => 'border-style:{{VALUE}} !important;' ) ) ) ) ); $this->add_responsive_control( 'btn_radius', array( 'label' => 'Border radius', 'type' => constant( "$cm::SLIDER" ), 'size_units' => array( 'px', '%' ), 'range' => array( 'px' => array( 'min' => 0, 'max' => 60 ) ), 'selectors' => array( $b => 'border-radius:{{SIZE}}{{UNIT}} !important;' ) ) ); $this->end_controls_section(); } protected function render() { $s = $this->get_settings_for_display(); $logo = hvm_get( 'event_logo' ); $logo_u = $logo ? hvm_img_url( $logo, 'full' ) : ''; $title = hvm_get( 'mixer_title' ); $title = ( '' !== (string) $title ) ? $title : get_the_title(); $raw = hvm_get( 'event_date' ); $dt = $raw ? date_create( str_replace( 'T', ' ', $raw ) ) : false; $date = $dt ? $dt->format( 'F j, Y' ) : ''; $status = $s['status_text'] ?? ''; $cta = ( isset( $s['cta_text'] ) && '' !== trim( (string) $s['cta_text'] ) ) ? $s['cta_text'] : 'Get Tickets'; $after = isset( $s['scroll_after'] ) && '' !== $s['scroll_after'] ? max( 0, (int) $s['scroll_after'] ) : 100; echo '<div class="hvm-sticky-dock" data-hvm-sticky-dock data-threshold="' . esc_attr( $after ) . '">'; echo '<div class="hvm-sticky">'; echo '<span class="hvm-sticky-logo">'; if ( $logo_u ) { echo '<img src="' . esc_url( $logo_u ) . '" alt="' . esc_attr( $title ) . '" />'; } echo '</span>'; echo '<div class="hvm-sticky-mid">'; if ( '' !== (string) $title ) { echo '<div class="hvm-sticky-title">' . esc_html( $title ) . '</div>'; } if ( '' !== $date || '' !== $status ) { echo '<div class="hvm-sticky-meta"><span class="hvm-sticky-dot" aria-hidden="true"></span>'; if ( '' !== $date ) { echo '<span>' . esc_html( $date ) . '</span>'; } if ( '' !== $date && '' !== $status ) { echo '<span class="hvm-sticky-sep">·</span>'; } if ( '' !== $status ) { echo '<span>' . esc_html( $status ) . '</span>'; } echo '</div>'; } echo '</div>'; echo '<div class="hvm-sticky-cta">'; $this->render_join_cta( $cta, 'light', 'hvm-sticky-btn' ); echo '</div>'; echo '</div>'; echo '</div>'; } } add_filter( 'hvm_mixer_widget_classes', function ( $classes ) { $classes[] = 'HVM_Widget_StickyProbar'; return $classes; } ); 